test('invoiceTotals VAT computed per line and summed', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 99, discountPercent: 0, vatRate: 21 }, // 99, vat 20.79 -> 21
      { qty: 1, unitPrice: 99, discountPercent: 0, vatRate: 21 }, // 99, vat 20.79 -> 21
      { qty: 1, unitPrice: 99, discountPercent: 0, vatRate: 21 }, // 99, vat 20.79 -> 21
    ],
  };

  const totals = invoiceTotals(invoice);
  // Each line: 99 * 21 / 100 = 20.79 -> rounds to 21
  // Total VAT should be 21 + 21 + 21 = 63, not 297 * 21 / 100 = 62.37 -> 62
  assert.equal(totals.vat, 63);
});
